import{_ as t,o as a,c as r,ai as o}from"./chunks/framework.Cg3BiOJh.js";const h=JSON.parse('{"title":"Privacy Policy","description":"Data practices for the Viable Prompt Protocol website, plugin, and public runtime.","frontmatter":{"title":"Privacy Policy","description":"Data practices for the Viable Prompt Protocol website, plugin, and public runtime."},"headers":[],"relativePath":"privacy/index.md","filePath":"privacy/index.md","lastUpdated":1786775408000}'),s={name:"privacy/index.md"};function i(n,e,c,d,p,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<p>Effective and last updated: August 15, 2026.</p><p>This policy explains the data practices for the Viable Prompt Protocol website, downloadable plugin and skill, and public runtime at <code>mcp.viableprompt.org</code>. VPP is an open-source project published by Seb Suarez.</p><h2 id="data-the-service-processes" tabindex="-1">Data the service processes <a class="header-anchor" href="#data-the-service-processes" aria-label="Permalink to &quot;Data the service processes&quot;">​</a></h2><p>The public runtime processes only the content supplied to the operation you choose: VPP commands, assistant responses, transparent client-carried state, or transcript turns. That content may contain personal data if you include it. The service does not require an account, request a user profile, read unrelated files, or collect contacts, payment details, or precise location data.</p><p>Cloudflare, the hosting and network provider, necessarily processes technical request information such as IP address, request headers, hostname, timing, and security signals to deliver and protect the service. The VPP website does not set first-party application cookies or use advertising trackers.</p><h2 id="why-the-data-is-used" tabindex="-1">Why the data is used <a class="header-anchor" href="#why-the-data-is-used" aria-label="Permalink to &quot;Why the data is used&quot;">​</a></h2><p>Submitted content is used only to perform the requested structural operation: prepare a turn, format a response, validate or repair an exchange, or validate a transcript. Technical request information is used to route traffic, enforce request-size and rate limits, prevent abuse, and maintain service availability.</p><p>VPP does not sell personal information, build advertising profiles, or use submitted content to train models.</p><h2 id="sharing-and-processors" tabindex="-1">Sharing and processors <a class="header-anchor" href="#sharing-and-processors" aria-label="Permalink to &quot;Sharing and processors&quot;">​</a></h2><p>Submitted content and technical request information are processed by Cloudflare as the infrastructure provider. VPP does not disclose submitted content to data brokers or advertising networks. A host such as ChatGPT, Codex, or another agent may process the same content under that host&#39;s own terms and privacy policy before or after it calls VPP.</p><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h2><p>The VPP application does not persist request bodies, responses, or conversation state. Application-level request-body logging and Worker observability are disabled, so VPP&#39;s application retention period for that content is zero beyond the time required to complete the request.</p><p>The service does not maintain user accounts or a server-side conversation database. Cloudflare may retain limited network, security, and abuse-prevention information under its own policies and infrastructure settings; VPP does not control those provider-level retention periods.</p><h2 id="your-choices-and-controls" tabindex="-1">Your choices and controls <a class="header-anchor" href="#your-choices-and-controls" aria-label="Permalink to &quot;Your choices and controls&quot;">​</a></h2><p>Do not submit secrets or personal data that are unnecessary for structural protocol processing. You can use the bundled offline script instead of the public endpoint, stop using the service at any time, and begin a new conversation without prior state. Because VPP stores no account or conversation record, it generally has no server-side content to access, correct, export, or delete after a request finishes.</p><p>For a privacy question or request, email <a href="mailto:contact@cbassuarez.com" target="_blank" rel="noreferrer">contact@cbassuarez.com</a> or use the public <a href="/support/">support page</a>. Include no sensitive transcript content in a public GitHub issue.</p>',16)])])}const m=t(s,[["render",i]]);export{h as __pageData,m as default};
